window.kbPageData["views/entry/k-72f8415a87009f9f"] = {"key":"entry/k-72f8415a87009f9f","state":{"route":"entry/k-72f8415a87009f9f"},"node":{"id":"k-72f8415a87009f9f","mode":"k","title":"一般公共预算支出","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["经济指标与宏观调控"],"资料类别":["非时政"]},"directorySummary":"3.一般公共预算支出\n一般公共预算支出指国家财政将筹集起来的资金进行分配使用，以满足经济建设和各项\n事业的需要。主要包括：一般公共服务、外交、国防、公共安全、教育、科学技术、文化体\n育与传媒、社会保障和就业、医疗卫生与计划生育、节能环保、城乡社区、农林水、交通运\n输、资源勘探信息等、商业服务业等、金…","sources":[{"id":"d1d03e4f5f7e9094","label":"一般公共预算支出","topic":"经济指标与宏观调控","category":"非时政","text":"3.一般公共预算支出\n一般公共预算支出指国家财政将筹集起来的资金进行分配使用，以满足经济建设和各项\n事业的需要。主要包括：一般公共服务、外交、国防、公共安全、教育、科学技术、文化体\n育与传媒、社会保障和就业、医疗卫生与计划生育、节能环保、城乡社区、农林水、交通运\n输、资源勘探信息等、商业服务业等、金融、援助其他地区、国土海洋气象等、住房保障、\n粮油物资储备、债务付息、债务发行费用等方面的支出。财政支出根据政府在经济和社会活\n动中的不同职权，划分为中央财政支出和地方财政支出。","source":{"doc":"6cbfb01fe723bba64b75","first":23,"last":23,"page":23,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-72f8415a87009f9f":[]}};
